-- ============================================================
-- Mundo de Artanis -- Habilidades
-- Tabelas de habilidades e seed gerado a partir do AbilityDatabase.json
-- Seguro para reexecutar. Arquivo 100% ASCII (acentos como hex) para nao
-- sofrer com a codificacao do PowerShell.
-- ============================================================

USE artanis_planner;

CREATE TABLE IF NOT EXISTS abilities (
    id               INT AUTO_INCREMENT PRIMARY KEY,
    game_id          VARCHAR(80) NOT NULL UNIQUE,
    numeric_id       INT,
    name             VARCHAR(100) NOT NULL,
    description      TEXT,
    class            VARCHAR(20) NOT NULL,
    max_level        INT DEFAULT 5,
    type             VARCHAR(40),
    element          VARCHAR(30) DEFAULT 'neutro',
    passive          BOOLEAN DEFAULT FALSE,
    guaranteed_hit   BOOLEAN DEFAULT FALSE,
    guaranteed_crit  BOOLEAN DEFAULT FALSE,
    mp_cost          JSON,
    multiplier       JSON,
    armor_pen        JSON,
    def_bonus        JSON,
    crit_bonus       JSON,
    num_hits         JSON,
    poison_damage    JSON,
    heal_percent     JSON
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS character_abilities (
    character_id INT NOT NULL,
    ability_id   INT NOT NULL,
    level        INT NOT NULL DEFAULT 1,
    PRIMARY KEY (character_id, ability_id),
    FOREIGN KEY (character_id) REFERENCES characters(id) ON DELETE CASCADE,
    FOREIGN KEY (ability_id)   REFERENCES abilities(id)   ON DELETE CASCADE
) ENGINE=InnoDB;

-- Remove registros gravados com acentos corrompidos ('?') numa importacao anterior
DELETE FROM abilities WHERE game_id LIKE '%?%';

